from math import gcd
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    if n < 2:
        return n
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def main() -> None:
    for m, n in [(12, 18), (9, 15), (10, 15), (8, 12), (7, 11), (20, 30)]:
        lhs, rhs = fib(gcd(m, n)), gcd(fib(m), fib(n))
        print(f'm={m} n={n}: F(gcd)={lhs} gcd(F,F)={rhs} '
              f"{'OK' if lhs == rhs else 'FAIL'}")
    # coprimality propagation
    for m, n in [(4, 9), (7, 11), (5, 8), (13, 21)]:
        assert gcd(m, n) == 1
        print(f'coprime {m},{n}: gcd(F,F)={gcd(fib(m), fib(n))}')

if __name__ == '__main__':
    main()

