from math import gcd
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    if n < 2:
        return n
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def rank(p: int) -> int:
    a, b = 0, 1
    k = 1
    while b % p != 0:
        a, b = b, (a + b) % p
        k += 1
    return k

def main() -> None:
    for p, m, n in [(2, 6, 9), (3, 8, 12), (5, 10, 15), (7, 8, 16)]:
        if fib(m) % p == 0 and fib(n) % p == 0:
            assert fib(gcd(m, n)) % p == 0
            print(f'descent p={p}: p|F(gcd({m},{n})) OK')
    for p in [2, 3, 5, 7, 11, 13, 17, 19, 23]:
        a = rank(p)
        ok = all((fib(n) % p == 0) == (n % a == 0) for n in range(1, 61))
        print(f'alpha({p})={a}  logarithm-test: '
              f"{'OK' if ok else 'EXCEPTIONAL' }")

if __name__ == '__main__':
    main()

